// Generated by scripts/write-examples.mjs from examples/*.ts. Do not edit by hand.

/** Each example script's source, by name (its file name without .ts). */
export const KIT_EXAMPLE_SOURCES: Readonly<Record<string, string>> = {
  "civil-site": "/**\n * Civil site grading and storm drainage: imports existing and proposed\n * LandXML 1.2 TIN surfaces, computes prismoidal cut and fill in cubic yards\n * and cubic metres, inspects the imported surfaces via `civil.grading_surfaces`,\n * and reports the earthwork takeoff.\n *\n * Run it: paste it to an assistant connected to the MutinyBIM tool server\n * (\"run this script\"), or `npm run example -- civil-site`.\n */\nimport { defineScript, units, building, documents } from \"@permitzip/bim-script\";\n\nconst ft = units.ft;\n\nconst SITE_LANDXML = `<?xml version=\"1.0\"?>\n<LandXML version=\"1.2\">\n  <Units><Imperial linearUnit=\"foot\"/></Units>\n  <Surfaces>\n    <Surface name=\"Existing Grade\">\n      <Definition surfType=\"TIN\">\n        <Pnts>\n          <P id=\"1\">0 0 100.0</P>\n          <P id=\"2\">0 100 98.0</P>\n          <P id=\"3\">80 100 99.5</P>\n          <P id=\"4\">80 0 101.5</P>\n          <P id=\"5\">40 50 99.75</P>\n        </Pnts>\n        <Faces>\n          <F>1 2 5</F>\n          <F>2 3 5</F>\n          <F>3 4 5</F>\n          <F>4 1 5</F>\n        </Faces>\n      </Definition>\n    </Surface>\n    <Surface name=\"Proposed Pad\">\n      <Definition surfType=\"TIN\">\n        <Pnts>\n          <P id=\"1\">0 0 100.0</P>\n          <P id=\"2\">0 100 100.0</P>\n          <P id=\"3\">80 100 100.0</P>\n          <P id=\"4\">80 0 100.0</P>\n          <P id=\"5\">40 50 100.0</P>\n        </Pnts>\n        <Faces>\n          <F>1 2 5</F>\n          <F>2 3 5</F>\n          <F>3 4 5</F>\n          <F>4 1 5</F>\n        </Faces>\n      </Definition>\n    </Surface>\n  </Surfaces>\n</LandXML>`;\n\nexport default defineScript({\n  kind: \"layout\",\n  reads: { levels: true },\n  parameters: {},\n  run(ctx) {\n    ctx.label(\"Civil site grading: import Existing and Proposed LandXML TINs, compute prismoidal cut/fill, and create sheet C-101\");\n\n    const siteLevel = building.level(ctx, { name: \"Site\", elevation: ft(0) });\n\n    // Import both LandXML 1.2 TIN surfaces onto the Site level.\n    ctx.edit({ type: \"civil.import_landxml_surfaces\", landXml: SITE_LANDXML, levelId: siteLevel });\n\n    // Compute prismoidal cut, fill, net (fill - cut), and overlap area.\n    const earthwork = ctx.calc({\n      calc: \"civil.surface_cut_fill\",\n      inputs: { existingId: \"gs-existing-grade\", proposedId: \"gs-proposed-pad\" },\n    });\n\n    // Place a civil site grading plan on Sheet C-101.\n    const sheet = documents.sheet(ctx, { number: \"C-101\", name: \"Civil Site Grading Plan\" });\n    const plan = documents.planView(ctx, { level: siteLevel, name: \"Site Grading Plan\", scale: 120 });\n    documents.place(ctx, sheet, plan, { x: units.mm(260), y: units.mm(260) });\n\n    ctx.report(\"Earthwork cut and fill\", earthwork);\n  },\n});\n",
  "commercial-kitchen-dwv-grease": "/**\n * Commercial kitchen DWV — segregated sanitary, grease waste, indirect /\n * clear-water waste, cleanouts, named soil stack & under-slab view:\n *\n * Models a commercial restaurant kitchen and restroom core with IPC-compliant\n * drainage segregation:\n *  - Sanitary waste (`san-1`) serving restroom WCs and lavatories into a named\n *    4\" vertical soil stack (`S-1` via `plumbing.manageStack`)\n *  - Dedicated grease waste (`gw-1`, `grease_waste`) serving the 3-compartment\n *    pot sink, floor sink, and mop sink through an inline 100 gpm grease\n *    interceptor (`builtin:plumbing-grease-interceptor@1`)\n *  - Dedicated indirect / clear-water waste (`cw-waste-1`) serving the\n *    ice-maker / prep floor drain kept separate from grease-laden piping per\n *    IPC 802.1\n *  - Automatic IPC 708 cleanout spacing (`plumbing.proposeCleanouts`) applied\n *    to both sanitary and grease mains\n *  - Under-slab plumbing plan (`viewBottom: ft(-4), viewDepth: ft(0)` — never\n *    negative `viewDepth`), live DWV riser diagram, and fixture schedule on P-101\n *\n * Run with `bim_run_script` or `npm run example -- commercial-kitchen-dwv-grease`.\n */\nimport { defineScript, units, building, equipment, routes, plumbing, documents } from \"@permitzip/bim-script\";\n\nconst { ft } = units;\nconst inch = units.in;\n\nexport default defineScript({\n  kind: \"layout\",\n  parameters: {},\n  reads: {},\n  run(ctx) {\n    const L1 = building.level(ctx, { id: \"L1\", name: \"Level 1\", elevation: ft(0) });\n    building.level(ctx, { id: \"ROOF\", name: \"Roof\", elevation: ft(14) });\n\n    building.walls(ctx, {\n      level: L1,\n      height: ft(14),\n      thickness: inch(8),\n      points: [\n        { x: ft(0), y: ft(0) },\n        { x: ft(56), y: ft(0) },\n        { x: ft(56), y: ft(30) },\n        { x: ft(0), y: ft(30) },\n      ],\n      closed: true,\n    });\n    building.wall(ctx, {\n      level: L1,\n      height: ft(14),\n      thickness: inch(6),\n      from: { x: ft(22), y: ft(0) },\n      to: { x: ft(22), y: ft(30) },\n    });\n\n    // Restroom fixtures (west zone) -> Sanitary waste (san-1).\n    const wc1 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-wc-flush-tank@1\", at: { x: ft(6), y: ft(4) }, mark: \"WC-1\" });\n    const wc2 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-wc-flush-tank@1\", at: { x: ft(12), y: ft(4) }, mark: \"WC-2\" });\n    const lav1 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-lavatory@1\", at: { x: ft(18), y: ft(4) }, mark: \"L-1\" });\n\n    // Kitchen grease-bearing fixtures (east zone) -> Grease waste (gw-1).\n    const sink3 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-sink-3@1\", at: { x: ft(28), y: ft(5) }, mark: \"SK-3\" });\n    const fsGrease = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-floor-sink@1\", at: { x: ft(36), y: ft(5) }, mark: \"FS-G1\" });\n    const mop = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-mop-sink@1\", at: { x: ft(44), y: ft(5) }, mark: \"MS-1\" });\n\n    // Clear-water / indirect waste fixture (north kitchen) -> kept separate from grease.\n    const fsClear = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-floor-sink@1\", at: { x: ft(34), y: ft(24) }, mark: \"FS-CW1\" });\n    const fdClear = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-floor-drain@1\", at: { x: ft(46), y: ft(24) }, mark: \"FD-CW1\" });\n\n    // 1. Sanitary under-slab main along y=10 ft, sloping west toward the street at 1/8\"/ft.\n    const sanMain = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(4), \"cast_iron\"),\n      system: { id: \"san-1\", kind: \"sanitary\", name: \"Sanitary Waste\" },\n      height: ft(-2),\n      slope: { rise: inch(0.125), per: ft(1) },\n      flow: \"with_points\",\n      points: [\n        { x: ft(20), y: ft(10) },\n        { x: ft(2), y: ft(10) },\n      ],\n    });\n    routes.connectInto(ctx, {\n      from: [\n        { elementId: wc1.id, port: \"w\" },\n        { elementId: wc2.id, port: \"w\" },\n        { elementId: lav1.id, port: \"w\" },\n      ],\n      into: sanMain.segment(1),\n    });\n\n    // Named vertical soil & vent stack at the restroom chase (x=3, y=14).\n    const soilStack = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(4), \"cast_iron\"),\n      system: { id: \"san-1\", kind: \"sanitary\", name: \"Sanitary Waste\" },\n      height: ft(-1.5),\n      points: [\n        { x: ft(3), y: ft(14), height: ft(-1.5) },\n        { x: ft(3), y: ft(14), height: ft(15) },\n      ],\n    });\n    plumbing.manageStack(ctx, {\n      action: \"name\",\n      pipeId: soilStack.segment(1),\n      number: \"S-1\",\n      name: \"Restroom Soil Stack\",\n      systemCode: \"SAN\",\n      serves: \"Level 1 Restrooms\",\n    });\n\n    // 2. Dedicated Grease Waste main along y=13 ft, sloping east out past the east\n    // exterior wall (x=56) to an exterior 100 gpm grease interceptor centered at x=63 ft\n    // (clear of the east wall footprint, with the pipe passing safely below slab at -2.5 ft).\n    const greaseMain = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(4), \"cast_iron\"),\n      system: { id: \"gw-1\", kind: \"sanitary\", name: \"Grease Waste\" },\n      height: ft(-2.5),\n      slope: { rise: inch(0.125), per: ft(1) },\n      flow: \"with_points\",\n      points: [\n        { x: ft(26), y: ft(13) },\n        { x: ft(68), y: ft(13) },\n      ],\n    });\n    // Place inline grease interceptor FIRST near the downstream end of the grease\n    // main (inline insertion splits the pipe; connecting fixtures afterward taps\n    // the upstream segment cleanly without dragging connected fixtures).\n    plumbing.placeAccessory(ctx, {\n      segment: greaseMain.segment(1),\n      fromEnd: ft(5),\n      partTypeId: \"builtin:plumbing-grease-interceptor@1\",\n      mark: \"GI-1\",\n    });\n    routes.connectInto(ctx, {\n      from: [\n        { elementId: sink3.id, port: \"w\" },\n        { elementId: fsGrease.id, port: \"w\" },\n        { elementId: mop.id, port: \"w\" },\n      ],\n      into: greaseMain.segment(1),\n    });\n\n    // 3. Dedicated Indirect / Clear-Water Waste along y=20 ft (completely separated\n    // from grease waste, discharging downstream of the interceptor).\n    const clearMain = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(3), \"pvc\"),\n      system: { id: \"iw-1\", kind: \"sanitary\", name: \"Indirect / Clear-Water Waste\" },\n      height: ft(-1.75),\n      slope: { rise: inch(0.25), per: ft(1) },\n      flow: \"with_points\",\n      points: [\n        { x: ft(48), y: ft(20) },\n        { x: ft(26), y: ft(20) },\n      ],\n    });\n    routes.connectInto(ctx, {\n      from: [\n        { elementId: fsClear.id, port: \"w\" },\n        { elementId: fdClear.id, port: \"w\" },\n      ],\n      into: clearMain.segment(1),\n    });\n\n    // Configure drainage slopes & apply IPC 708 cleanout spacing + drain sizing.\n    plumbing.setSystemDesign(ctx, \"san-1\", {\n      slopes: [\n        { maxNominalIn: 2.5, inPerFt: 0.25 },\n        { maxNominalIn: 12, inPerFt: 0.125 },\n      ],\n    });\n    plumbing.setSystemDesign(ctx, \"gw-1\", {\n      slopes: [\n        { maxNominalIn: 2.5, inPerFt: 0.25 },\n        { maxNominalIn: 12, inPerFt: 0.125 },\n      ],\n    });\n\n    const sanCleanouts = plumbing.proposeCleanouts(ctx, { system: \"san-1\", spacing: ft(50), apply: true });\n    const greaseCleanouts = plumbing.proposeCleanouts(ctx, { system: \"gw-1\", spacing: ft(50), apply: true });\n    const sanSized = plumbing.sizeSystem(ctx, { system: \"san-1\", apply: true, plumbingEdition: \"2021\" });\n    const greaseSized = plumbing.sizeSystem(ctx, { system: \"gw-1\", apply: true, plumbingEdition: \"2021\" });\n\n    // Under-slab DWV plan: viewBottom is signed negative (-4 ft); viewDepth is ALWAYS >= 0!\n    const underSlabPlan = documents.planView(ctx, {\n      level: L1,\n      name: \"Level 1 - Under-Slab DWV & Grease Plan\",\n      discipline: \"plumbing\",\n      scale: 48,\n      cutHeight: ft(2),\n      viewTop: ft(2),\n      viewBottom: ft(-4),\n      viewDepth: ft(0),\n      browserGroup: \"Plumbing\",\n      sortOrder: 101,\n      detailLevel: \"medium\",\n    });\n    const dwvRiser = documents.diagram(ctx, {\n      name: \"Commercial Kitchen DWV & Grease Riser\",\n      kind: \"plumbing_riser\",\n    });\n    const fixtureSchedule = documents.schedule(ctx, {\n      name: \"DWV Fixture & Interceptor Schedule\",\n      category: \"plumbing_fixture\",\n      columns: [\"mark\", \"type_name\", \"level\"],\n    });\n\n    const sheet = documents.sheet(ctx, {\n      number: \"P-101\",\n      name: \"Under-Slab DWV, Grease & Indirect Waste\",\n      discipline: \"plumbing\",\n      sortOrder: 101,\n    });\n    documents.place(ctx, sheet, underSlabPlan, { x: units.mm(230), y: units.mm(420) });\n    documents.place(ctx, sheet, dwvRiser, { x: units.mm(640), y: units.mm(420) }, 1);\n    documents.place(ctx, sheet, fixtureSchedule, { x: units.mm(230), y: units.mm(150) });\n\n    ctx.report(\"Commercial kitchen DWV & grease\", {\n      sanCleanoutsPlaced: sanCleanouts.placedIds.length,\n      greaseCleanoutsPlaced: greaseCleanouts.placedIds.length,\n      sanSizedUpdates: sanSized.appliedCount,\n      greaseSizedUpdates: greaseSized.appliedCount,\n    });\n    ctx.label(\"Commercial kitchen DWV + grease + indirect waste modeled and documented on sheet P-101\");\n  },\n});\n",
  "domestic-water-recirc-pressure-loss": "/**\n * Commercial domestic water — service entrance, RPZ backflow, water heater,\n * expansion tank, DHWR recirculation loop, pipe insulation & pressure loss:\n *\n * Models a commercial domestic cold/hot/recirculation piping plant:\n *  - Street service entrance with WS-1 hydrant flow test curve (`flowTest`)\n *  - Inline RPZ backflow preventer and cold water main feeding flushometer WCs,\n *    lavatories, and a 3-compartment kitchen sink\n *  - 100 gal gas water heater + thermal expansion tank\n *  - Insulated DHW supply + DHWR return loop with balancing valve, check valve,\n *    and recirculation design settings (`dhwr`)\n *  - IECC 2021 Table C403.12.3 pipe insulation schedule applied to DHW/DHWR\n *  - Full IPC 2021 pipe sizing and pressure-loss report (`plumbing.waterReport`)\n *  - Domestic Water Plan, Live Plumbing Riser Diagram, and Fixture Schedule on P-201\n *\n * Run with `bim_run_script` or `npm run example -- domestic-water-recirc-pressure-loss`.\n */\nimport { defineScript, units, building, equipment, routes, plumbing, documents } from \"@permitzip/bim-script\";\n\nconst { ft } = units;\nconst inch = units.in;\n\nexport default defineScript({\n  kind: \"layout\",\n  parameters: {},\n  reads: {},\n  run(ctx) {\n    const L1 = building.level(ctx, { id: \"L1\", name: \"Level 1\", elevation: ft(0) });\n    building.level(ctx, { id: \"ROOF\", name: \"Roof\", elevation: ft(14) });\n\n    building.walls(ctx, {\n      level: L1,\n      height: ft(14),\n      thickness: inch(8),\n      points: [\n        { x: ft(0), y: ft(0) },\n        { x: ft(48), y: ft(0) },\n        { x: ft(48), y: ft(28) },\n        { x: ft(0), y: ft(28) },\n      ],\n      closed: true,\n    });\n\n    // Water heater + thermal expansion tank in the mechanical corner.\n    const wh = equipment.place(ctx, {\n      level: L1,\n      type: \"builtin:plumbing-water-heater-tank@1\",\n      at: { x: ft(6), y: ft(20) },\n      mark: \"WH-1\",\n    });\n    const expTank = equipment.place(ctx, {\n      level: L1,\n      type: \"builtin:plumbing-expansion-tank@1\",\n      at: { x: ft(10), y: ft(20) },\n      height: ft(5),\n      mark: \"ET-1\",\n    });\n\n    // Commercial restroom + kitchen fixtures along the south wall.\n    const wc1 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-wc-flushometer@1\", at: { x: ft(18), y: ft(3) }, mark: \"WC-1\" });\n    const wc2 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-wc-flushometer@1\", at: { x: ft(23), y: ft(3) }, mark: \"WC-2\" });\n    const lav1 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-lavatory@1\", at: { x: ft(29), y: ft(3) }, mark: \"L-1\" });\n    const lav2 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-lavatory@1\", at: { x: ft(34), y: ft(3) }, mark: \"L-2\" });\n    const sink3 = equipment.place(ctx, { level: L1, type: \"builtin:plumbing-sink-3@1\", at: { x: ft(42), y: ft(4) }, mark: \"SK-3\" });\n\n    // Cold water main (DCW) at 10'-6\" AFF along y=12 ft; separated vertically and\n    // laterally from DHW (9'-8\" AFF, y=14 ft) and DHWR (9'-0\" AFF, y=16 ft) so\n    // parallel headers stay completely clash-free.\n    const dcwMain = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(2), \"copper\"),\n      system: { id: \"dcw-1\", kind: \"domestic_cold_water\", name: \"Domestic Cold Water\" },\n      height: ft(10.5),\n      points: [\n        { x: ft(1), y: ft(12) },\n        { x: ft(44), y: ft(12) },\n      ],\n    });\n\n    routes.connectInto(ctx, {\n      from: [\n        { elementId: wh.id, port: \"cw\" },\n        { elementId: expTank.id, port: \"cw\" },\n        { elementId: wc1.id, port: \"cw\" },\n        { elementId: wc2.id, port: \"cw\" },\n        { elementId: lav1.id, port: \"cw\" },\n        { elementId: lav2.id, port: \"cw\" },\n        { elementId: sink3.id, port: \"cw\" },\n      ],\n      into: dcwMain.segment(1),\n    });\n\n    // Main shutoff valve and inline RPZ backflow preventer near the service entry.\n    // Place hosted accessories before inline part insertion (RPZ splits the host pipe).\n    plumbing.placeAccessory(ctx, {\n      segment: dcwMain.segment(1),\n      at: ft(1.5),\n      kind: \"ball_valve\",\n      mark: \"BV-CW1\",\n    });\n    plumbing.placeAccessory(ctx, {\n      segment: dcwMain.segment(1),\n      at: ft(3.5),\n      kind: \"rpz\",\n      mark: \"RPZ-1\",\n    });\n\n    // Domestic Hot Water (DHW) header at 9'-8\" AFF along y=14 ft.\n    const dhwMain = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(1.25), \"copper\"),\n      system: { id: \"dhw-1\", kind: \"domestic_hot_water\", name: \"Domestic Hot Water\" },\n      height: ft(9.67),\n      points: [\n        { x: ft(8), y: ft(14) },\n        { x: ft(44), y: ft(14) },\n      ],\n    });\n    routes.connectInto(ctx, {\n      from: [\n        { elementId: wh.id, port: \"hw\" },\n        { elementId: lav1.id, port: \"hw\" },\n        { elementId: lav2.id, port: \"hw\" },\n        { elementId: sink3.id, port: \"hw\" },\n      ],\n      into: dhwMain.segment(1),\n    });\n\n    // Domestic Hot Water Return (DHWR) loop at 9'-0\" AFF along y=16 ft back toward WH-1.\n    const dhwrMain = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(0.75), \"copper\"),\n      system: { id: \"dhwr-1\", kind: \"domestic_hot_water_return\", name: \"Domestic Hot Water Return\" },\n      height: ft(9.0),\n      points: [\n        { x: ft(42), y: ft(16) },\n        { x: ft(8), y: ft(16) },\n      ],\n    });\n\n    // Balancing valve and check valve on the DHWR loop near the water heater.\n    plumbing.placeAccessory(ctx, {\n      segment: dhwrMain.segment(1),\n      at: ft(24),\n      kind: \"balancing_valve\",\n      mark: \"CBV-1\",\n    });\n    plumbing.placeAccessory(ctx, {\n      segment: dhwrMain.segment(1),\n      at: ft(28),\n      kind: \"check_valve\",\n      mark: \"CV-1\",\n    });\n\n    // Configure DCW hydrant flow-test curve + ASHRAE demand curve, DHW, and DHWR loop metadata.\n    plumbing.setSystemDesign(ctx, \"dcw-1\", {\n      demandCurve: \"ashrae_d\",\n      staticPressurePsi: 65,\n      fixedLossesPsi: 15,\n      minFixturePressurePsi: 25,\n      maxVelocityFps: 8,\n      flowTest: {\n        staticPsi: 65,\n        residualPsi: 52,\n        testGpm: 120,\n        elevationFt: 0,\n        safetyMarginPsi: 5,\n        location: \"Main St Hydrant #14\",\n      },\n    });\n    plumbing.setSystemDesign(ctx, \"dhw-1\", {\n      demandCurve: \"ashrae_d\",\n      staticPressurePsi: 60,\n      fixedLossesPsi: 16,\n      minFixturePressurePsi: 15,\n      maxVelocityFps: 5,\n      waterTempF: 140,\n    });\n    plumbing.setSystemDesign(ctx, \"dhwr-1\", {\n      maxVelocityFps: 4,\n      waterTempF: 130,\n      dhwr: {\n        deltaTF: 10,\n        heatLossBtuPerHrFt: 12,\n        maxVelocityFps: 4,\n        supplyTempF: 140,\n        returnTempF: 130,\n        pumpGpm: 6,\n        pumpHeadFt: 12,\n      },\n    });\n\n    // Apply IECC 2021 pipe insulation schedule to DHW and DHWR systems.\n    plumbing.setInsulationSchedule(ctx, {\n      rows: [\n        {\n          systemKinds: [\"domestic_hot_water\", \"domestic_hot_water_return\"],\n          belowNominal: inch(1.5),\n          thickness: inch(1),\n          material: \"fiberglass\",\n        },\n        {\n          systemKinds: [\"domestic_hot_water\", \"domestic_hot_water_return\"],\n          belowNominal: inch(48),\n          thickness: inch(1.5),\n          material: \"fiberglass\",\n        },\n      ],\n      source: \"IECC 2021 Table C403.12.3\",\n      buildingType: \"restaurant\",\n      demandCurve: \"ipc_e_valve\",\n      applyToSystems: [\"dhw-1\", \"dhwr-1\"],\n    });\n\n    // Size DCW and DHW systems and run the domestic water pressure-loss report.\n    const dcwSized = plumbing.sizeSystem(ctx, { system: \"dcw-1\", apply: true, plumbingEdition: \"2021\" });\n    const dhwSized = plumbing.sizeSystem(ctx, { system: \"dhw-1\", apply: true, plumbingEdition: \"2021\" });\n    const waterReport = plumbing.waterReport(ctx, \"dcw-1\", {\n      plumbingEdition: \"2021\",\n      pressure: {\n        supplyKind: \"flow_test\",\n        supplyPsi: 65,\n        meterLossPsi: 4,\n        backflowLossPsi: 12,\n        backflowDevice: \"RPZ\",\n        highestFixtureHeight: ft(4),\n        criticalFixture: \"WC-2 (Flushometer)\",\n        criticalFixturePsi: 25,\n        developedLength: ft(95),\n      },\n    });\n\n    // Documents: Domestic Water Plan, Live Plumbing Riser Diagram, Fixture & Pipe Schedules.\n    const waterPlan = documents.planView(ctx, {\n      level: L1,\n      name: \"Level 1 - Domestic Water Plan\",\n      discipline: \"plumbing\",\n      scale: 48,\n      viewTopRef: \"level_above\",\n      viewBottom: ft(0),\n      viewDepth: ft(0),\n      browserGroup: \"Plumbing\",\n      sortOrder: 201,\n      detailLevel: \"medium\",\n    });\n    const waterRiser = documents.diagram(ctx, {\n      name: \"Domestic Water & DHWR Riser Diagram\",\n      kind: \"plumbing_riser\",\n    });\n    const fixtureSchedule = documents.schedule(ctx, {\n      name: \"Plumbing Fixture Schedule\",\n      category: \"plumbing_fixture\",\n      columns: [\"mark\", \"type_name\", \"level\"],\n    });\n\n    const sheet = documents.sheet(ctx, {\n      number: \"P-201\",\n      name: \"Domestic Water, DHWR & Pressure Loss\",\n      discipline: \"plumbing\",\n      sortOrder: 201,\n    });\n    documents.place(ctx, sheet, waterPlan, { x: units.mm(230), y: units.mm(420) });\n    documents.place(ctx, sheet, waterRiser, { x: units.mm(640), y: units.mm(420) }, 1);\n    documents.place(ctx, sheet, fixtureSchedule, { x: units.mm(230), y: units.mm(150) });\n\n    ctx.report(\"Domestic water & pressure loss\", {\n      totalWsfu: waterReport.totalWsfu,\n      designGpm: waterReport.designGpm,\n      availablePsi: waterReport.availablePsi,\n      allowablePsiPer100Ft: waterReport.allowablePsiPer100Ft,\n      dcwUpdates: dcwSized.appliedCount,\n      dhwUpdates: dhwSized.appliedCount,\n    });\n    ctx.label(`Domestic water + DHWR loop sized (${dcwSized.appliedCount + dhwSized.appliedCount} updates) on sheet P-201`);\n  },\n});\n",
  "electrical-room": "/**\n * Electrical room: a one-bedroom unit's receptacles, circuits and panel\n * schedule.\n *\n * The script draws the unit's walls and rooms, places a panel, lets the\n * Electrical add-on propose receptacles by the code's wall spacing (NEC\n * 210.52: no point along a wall more than 6 ft from a receptacle), places\n * them, circuits them with a room template (one circuit per room), and puts\n * the panel's schedule on a sheet. The schedule prints the panel's loads\n * with the code's demand factors.\n *\n * Run it: paste it to an assistant connected to the MutinyBIM tool server\n * (\"run this script\"), or `npm run example -- electrical-room`.\n */\nimport { defineScript, units, building, equipment, documents } from \"@permitzip/bim-script\";\n\nconst ft = units.ft;\nconst at = (x: number, y: number) => ({ x: ft(x), y: ft(y) });\nconst box = (x0: number, x1: number) => [at(x0, 0), at(x1, 0), at(x1, 14), at(x0, 14)];\nconst NEC = \"2023\";\n\nexport default defineScript({\n  kind: \"layout\",\n  reads: { levels: true },\n  parameters: {},\n  run(ctx) {\n    const level = building.level(ctx, { name: \"Level 1\", elevation: ft(0) });\n\n    // A 32 ft x 14 ft unit: a bedroom and a living room, split by a wall at 14 ft.\n    building.walls(ctx, { level, points: box(0, 32), closed: true, thickness: units.in(6), height: ft(9) });\n    building.walls(ctx, { level, points: [at(14, 0), at(14, 14)], thickness: units.in(4), height: ft(9) });\n    const bedroom = building.room(ctx, { level, number: \"101\", name: \"Bedroom\", outline: box(0, 14) });\n    const living = building.room(ctx, { level, number: \"102\", name: \"Living room\", outline: box(14, 32) });\n\n    // The unit's panel, on the bedroom wall.\n    const panel = equipment.place(ctx, { level, type: \"builtin:panelboard-125-208-1ph@1\", at: at(1, 13), mark: \"LP-1\" });\n\n    // Receptacles by code spacing: the add-on proposes them, with the clause for each; the script keeps them all.\n    const proposal = ctx.propose(\"electrical.receptacles\", { typeId: \"builtin:duplex-receptacle@1\", roomIds: [bedroom, living], options: { mode: \"dwelling\", edition: NEC } });\n    ctx.acceptGhosts(proposal.ghosts, proposal.summary);\n\n    // One circuit per room, from a room template the script saves into the model.\n    ctx.edit({ type: \"save_catalog_entry\", entry: { type: \"circuit_template\", name: \"One-bedroom unit\", description: \"Each room's receptacles on their own circuit\", rules: [{ room: \"bedroom\", devices: \"receptacles\" }, { room: \"living\", devices: \"receptacles\" }] } });\n    const circuits = ctx.read<{ command: unknown; message: string }>(\"electrical.circuit_template_plan\", { template: \"One-bedroom unit\", units: [{ panel: \"LP-1\", rooms: [\"101\", \"102\"] }] });\n    ctx.editSteps(circuits.command);\n\n    // The panel's loads with the code's demand factors, and its schedule on a sheet printed by the same rules.\n    const loads = ctx.read<{ connectedVa: number; demand: { demandVa: number }; rules: { id: string } }>(\"electrical.loads\", { panel: \"LP-1\", nec_edition: NEC });\n    const schedule = documents.formSchedule(ctx, { kind: \"panel\", name: \"Panel LP-1 schedule\", element: panel.id, rules: loads.rules.id });\n    const sheet = documents.sheet(ctx, { number: \"E-601\", name: \"Panel schedules\" });\n    documents.place(ctx, sheet, schedule, { x: units.mm(250), y: units.mm(350) });\n\n    // A power plan of the unit on its own sheet.\n    const plan = documents.planView(ctx, { level, name: \"Level 1 - Power\", scale: 48, discipline: \"electrical\" });\n    const planSheet = documents.sheet(ctx, { number: \"E-101\", name: \"Level 1 power plan\" });\n    documents.place(ctx, planSheet, plan, { x: units.mm(300), y: units.mm(280) });\n\n    ctx.label(`${proposal.ghosts.length} receptacles (${proposal.passes ? \"meets\" : \"short of\"} NEC 210.52), ${circuits.message.toLowerCase()} LP-1 ${Math.round(loads.connectedVa)} VA connected`);\n  },\n});\n",
  "fuel-gas-hybrid-pressure": "/**\n * Commercial fuel gas — hybrid 2 psi / 7 in. w.c. system:\n *\n * Models a commercial kitchen & mechanical room supplied at 2 psi medium\n * pressure from the gas service entry, stepped down through an inline line\n * pressure regulator (7 in. w.c. outlet, 0.5 in. w.c. drop, vent limiter) to\n * feed commercial cooking appliances (gas range, gas fryer, gas flat-top grill)\n * and a tank water heater with shutoff valves, drip legs, and combustion flue\n * / intake venting.\n *\n * Uses the `plumbing` kit to configure IFGC 2021 longest-length design inputs,\n * place the regulator/shutoff/drip leg, run zone-by-zone IFGC 402.4 gas sizing,\n * apply the sized pipe diameters, and produce a gas plan, live plumbing riser\n * diagram, and gas appliance & pipe schedules on sheet P-401.\n *\n * Run with `bim_run_script` or `npm run example -- fuel-gas-hybrid-pressure`.\n */\nimport { defineScript, units, building, equipment, parts, routes, plumbing, documents } from \"@permitzip/bim-script\";\n\nconst { ft } = units;\nconst inch = units.in;\n\nexport default defineScript({\n  kind: \"layout\",\n  parameters: {},\n  reads: {},\n  run(ctx) {\n    const L1 = building.level(ctx, { id: \"L1\", name: \"Level 1\", elevation: ft(0) });\n    building.level(ctx, { id: \"ROOF\", name: \"Roof\", elevation: ft(14) });\n\n    // Simple kitchen + mechanical room envelope (44 ft x 24 ft).\n    building.walls(ctx, {\n      level: L1,\n      height: ft(14),\n      thickness: inch(8),\n      points: [\n        { x: ft(0), y: ft(0) },\n        { x: ft(44), y: ft(0) },\n        { x: ft(44), y: ft(24) },\n        { x: ft(0), y: ft(24) },\n      ],\n      closed: true,\n    });\n    building.wall(ctx, {\n      level: L1,\n      height: ft(9.5),\n      thickness: inch(6),\n      from: { x: ft(14), y: ft(0) },\n      to: { x: ft(14), y: ft(24) },\n    });\n\n    // Utility gas meter at service entry (2 psi outlet, flowDirection: \"out\").\n    // PartBuilder's \"front\" face points +X (east); a 12 in. tall box at 10'-0\"\n    // AFF places its mid-height gas outlet right at 10'-6\" AFF.\n    const meterPart = parts.part(\"Gas meter\", { type: \"2 psi Commercial\", category: \"pipe_accessory\" });\n    meterPart.box({ length: inch(14), width: inch(10), height: inch(12) });\n    meterPart.connector(\"front\", {\n      id: \"g\",\n      label: \"Gas Outlet\",\n      domain: \"pipe\",\n      systemKind: \"natural_gas\",\n      shape: \"round\",\n      diameter: inch(1.25),\n      flowDirection: \"out\",\n    });\n    ctx.edit({\n      type: \"save_part_types\",\n      label: \"Gas meter, 2 psi Commercial\",\n      types: [{ typeId: \"example.gas.meter.2psi\", definition: meterPart.build() }],\n    });\n    const meter = equipment.place(ctx, {\n      level: L1,\n      type: \"example.gas.meter.2psi\",\n      at: { x: ft(2), y: ft(10) },\n      height: ft(10),\n      mark: \"GM-1\",\n    });\n\n    // Gas-fired commercial kitchen appliances + mechanical room water heater.\n    const wh = equipment.place(ctx, {\n      level: L1,\n      type: \"builtin:plumbing-water-heater-tank@1\",\n      at: { x: ft(6), y: ft(6) },\n      mark: \"WH-1\",\n    });\n    const range = equipment.place(ctx, {\n      level: L1,\n      type: \"builtin:plumbing-gas-range@1\",\n      at: { x: ft(22), y: ft(4) },\n      mark: \"GR-1\",\n    });\n    const fryer = equipment.place(ctx, {\n      level: L1,\n      type: \"builtin:plumbing-gas-fryer@1\",\n      at: { x: ft(29), y: ft(4) },\n      mark: \"GF-1\",\n    });\n    const grill = equipment.place(ctx, {\n      level: L1,\n      type: \"builtin:plumbing-gas-grill@1\",\n      at: { x: ft(36), y: ft(4) },\n      mark: \"GG-1\",\n    });\n\n    // Black-steel natural gas overhead main (10'-6\" AFF, clearing the 9'-6\"\n    // partition wall in the ceiling plenum). Medium-pressure (2 psi) from GM-1\n    // to the line regulator at x=12 ft, stepping down to 7 in. w.c. for the\n    // commercial kitchen manifold.\n    const gasSystem = { id: \"gas-1\", kind: \"natural_gas\" as const, name: \"Natural Gas (2 psi / 7 in. w.c.)\" };\n    const main = routes.along(ctx, {\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(1.25), \"black_steel\"),\n      system: gasSystem,\n      height: ft(10.5),\n      from: routes.atConnector(meter.id, \"g\"),\n      points: [{ x: ft(38), y: ft(10) }],\n    });\n    // Vertical service drop off the main for the sediment trap / drip leg.\n    const dripDrop = routes.branch(ctx, {\n      trunk: main.segment(1),\n      face: \"bottom\",\n      level: L1,\n      domain: \"pipe\",\n      size: routes.pipe(inch(1), \"black_steel\"),\n      system: gasSystem,\n      height: ft(10.5),\n      points: [\n        { x: ft(16), y: ft(10), height: ft(10.5) },\n        { x: ft(16), y: ft(10), height: ft(4) },\n      ],\n    });\n\n    // Connect all four appliances onto the overhead gas header with clean spacing in X.\n    routes.connectInto(ctx, {\n      from: [\n        { elementId: wh.id, port: \"g\" },\n        { elementId: range.id, port: \"g\" },\n        { elementId: fryer.id, port: \"g\" },\n        { elementId: grill.id, port: \"g\" },\n      ],\n      into: main.segment(1),\n    });\n\n    // Configure hybrid 2 psi inlet pressure + 1 psi allowable drop (IFGC 402.4\n    // longest-length method, 1000 Btu/cf natural gas) and appliance MBH inputs.\n    plumbing.setSystemDesign(ctx, \"gas-1\", {\n      fuel: \"natural_gas\",\n      inletPressurePsi: 2,\n      allowableDropPsi: 1,\n      gasSizing: \"longest_length\",\n      heatingValueBtuPerCf: 1000,\n      fixtureTable: [\n        { fixture: \"Water heater, tank\", mbh: 199 },\n        { fixture: \"Gas range\", mbh: 220 },\n        { fixture: \"Gas fryer\", mbh: 120 },\n        { fixture: \"Gas flat top grill\", mbh: 90 },\n      ],\n    });\n\n    // Place sediment trap / drip leg on the vertical drop, plus service shutoff\n    // valve and 2 psi → 7 in. w.c. line regulator on the overhead main.\n    plumbing.placeAccessory(ctx, {\n      segment: dripDrop.segment(1),\n      at: ft(2),\n      kind: \"drip_leg\",\n      nippleLength: inch(4),\n      mark: \"DL-1\",\n    });\n    plumbing.placeAccessory(ctx, {\n      segment: main.segment(1),\n      at: ft(2.5),\n      kind: \"gas_shutoff\",\n      mark: \"GV-MAIN\",\n    });\n    plumbing.placeAccessory(ctx, {\n      segment: main.segment(1),\n      at: ft(12),\n      kind: \"gas_regulator\",\n      regulator: {\n        role: \"line\",\n        outletInWc: 7,\n        dropInWc: 0.5,\n        vent: \"vent_limiter\",\n      },\n      mark: \"REG-1\",\n    });\n\n    // Route Category IV PVC combustion exhaust + intake from the tank water heater\n    // straight up through the roof, offset well clear of the overhead gas header.\n    plumbing.connectCombustionVent(ctx, {\n      equipment: wh,\n      level: L1,\n      termination: { x: ft(6), y: ft(18), height: ft(16) },\n      exhaust: { diameter: inch(4), material: \"pvc\" },\n      intake: { diameter: inch(4), material: \"pvc\", offset: { x: ft(2), y: ft(0) } },\n    });\n\n    // Run IFGC 2021 zone-by-zone gas sizing and apply the proposed nominal sizes.\n    const sized = plumbing.sizeSystem(ctx, {\n      system: \"gas-1\",\n      apply: true,\n      allowSmaller: true,\n      fuelGasEdition: \"2021\",\n    });\n    const gasReport = plumbing.gasReport(ctx, \"gas-1\", { fuelGasEdition: \"2021\" });\n\n    // Documents: Fuel Gas Plan, Live Plumbing Riser Diagram, Appliance & Pipe Schedules.\n    const gasPlan = documents.planView(ctx, {\n      level: L1,\n      name: \"Level 1 - Fuel Gas Plan\",\n      discipline: \"plumbing\",\n      scale: 48,\n      viewTopRef: \"level_above\",\n      viewBottom: ft(0),\n      viewDepth: ft(0),\n      browserGroup: \"Plumbing\",\n      sortOrder: 401,\n      detailLevel: \"medium\",\n    });\n    const gasRiser = documents.diagram(ctx, {\n      name: \"Fuel Gas Riser Diagram\",\n      kind: \"plumbing_riser\",\n    });\n    const applianceSchedule = documents.schedule(ctx, {\n      name: \"Gas Appliance Schedule\",\n      category: \"plumbing_fixture\",\n      columns: [\"mark\", \"type_name\", \"level\"],\n    });\n    const pipeSchedule = documents.schedule(ctx, {\n      name: \"Fuel Gas Pipe Schedule\",\n      category: \"pipe\",\n      columns: [\"system_name\", \"size\", \"length\", \"level\"],\n    });\n\n    const sheet = documents.sheet(ctx, {\n      number: \"P-401\",\n      name: \"Fuel Gas Plan, Riser & Schedules\",\n      discipline: \"plumbing\",\n      sortOrder: 401,\n    });\n    documents.place(ctx, sheet, gasPlan, { x: units.mm(230), y: units.mm(420) });\n    documents.place(ctx, sheet, gasRiser, { x: units.mm(640), y: units.mm(420) }, 1);\n    documents.place(ctx, sheet, applianceSchedule, { x: units.mm(220), y: units.mm(150) });\n    documents.place(ctx, sheet, pipeSchedule, { x: units.mm(560), y: units.mm(150) });\n\n    ctx.report(\"Fuel gas sizing & pressure zones\", {\n      totalMbh: gasReport.totalMbh,\n      zones: gasReport.zones.length,\n      appliedSizes: sized.appliedCount,\n      changes: sized.changes.map((c) => `${c.label}: ${c.currentLabel ?? \"?\"} -> ${c.proposedLabel}`),\n      findings: gasReport.findings.length,\n    });\n    ctx.label(`Hybrid 2 psi / 7 in. w.c. fuel gas system sized (${sized.appliedCount} pipe updates) on sheet P-401`);\n  },\n});\n",
  "mechanical-details": "/**\n * Mechanical details sheet: two permit-ready HVAC drafting details built with\n * the `drafting` CAD API, placed onto sheet M-501:\n *\n * 1. Carrier 50FEQ Rooftop Unit on 14\" Insulated Roof Curb with Ruskin 01-530\n *    Concentric Diffuser & Acoustic Dog-Leg Duct Offset (3/4\" = 1'-0\").\n * 2. Ceiling Toilet Exhaust Fan (EF-1A/1B) & 6\" Ø Exterior Hooded Wall Cap\n *    with Backdraft Damper & 1/4\" Bird Screen (3/4\" = 1'-0\").\n *\n * Demonstrates full CAD drafting standards: lineweight hierarchy (wide/medium/\n * thin/hidden/centerline), halftone & screened material hatches, mechanical 2D\n * detail components, break lines with cut masks, batt insulation, real CAD\n * dimensions, aligned left/right callout stacks with filled NCS arrowheads and\n * opaque text masks, tight crop fitting, and automated overlap QA.\n */\nimport { defineScript, units, documents, drafting } from \"@permitzip/bim-script\";\n\nconst inch = units.in;\nconst pt = (x: number, y: number) => ({ x: inch(x), y: inch(y) });\n\nexport default defineScript({\n  kind: \"layout\",\n  reads: {},\n  parameters: {},\n  run(ctx) {\n    // ── DETAIL 1: CARRIER 50FEQ RTU ON 14\" CURB & CONCENTRIC DIFFUSER DOG-LEG ──\n    const rtuDetail = drafting.view(ctx, {\n      name: \"RTU ON 14\\\" CURB & CONCENTRIC DIFFUSER DETAIL\",\n      scale: 16, // 3/4\" = 1'-0\"\n      discipline: \"mechanical\",\n    });\n\n    // Clearances (dashed thin envelopes flanking the unit, sitting flush on curb top y = 15.5)\n    drafting.rect(ctx, { view: rtuDetail, at: pt(-48, 15.5), width: inch(48), height: inch(34), lineStyle: \"hidden\" });\n    drafting.rect(ctx, { view: rtuDetail, at: pt(64, 15.5), width: inch(36), height: inch(34), lineStyle: \"hidden\" });\n\n    // Roof assembly: metal deck (-5.5 to -2) + rigid insulation (-2 to 1.5) + roofing membrane (y = 1.5)\n    // Curb rails sit cleanly at x = 0.8..4 (left) and x = 60..63.2 (right), resting on the roof assembly with cant strips flush on the membrane (y = 1.5)\n    for (const [rx, rw] of [[-46, 50], [60, 38]] as const) {\n      drafting.region(ctx, {\n        view: rtuDetail,\n        rect: { at: pt(rx, -5.5), width: inch(rw), height: inch(3.5) },\n        hatch: \"metal_deck\",\n        tone: \"halftone\",\n        lineStyle: \"medium\",\n      });\n      drafting.region(ctx, {\n        view: rtuDetail,\n        rect: { at: pt(rx, -2), width: inch(rw), height: inch(3.5) },\n        hatch: \"insulation_rigid\",\n        tone: \"screened\",\n        lineStyle: \"thin\",\n      });\n      drafting.line(ctx, { view: rtuDetail, from: pt(rx, 1.5), to: pt(rx + rw, 1.5), lineStyle: \"wide\" });\n    }\n    // Clean vertical break lines terminating both ends of the roof section (set slightly inboard so the cut mask slices cleanly through the hatched assembly)\n    drafting.breakLine(ctx, { view: rtuDetail, from: pt(-44, -7.5), to: pt(-44, 4), maskSide: \"left\", maskDepth: inch(5) });\n    drafting.breakLine(ctx, { view: rtuDetail, from: pt(96, -7.5), to: pt(96, 4), maskSide: \"right\", maskDepth: inch(5) });\n\n    // 14\" insulated roof curb rails (left & right mirrored) sitting flush on top of roof membrane (y = 1.5 -> 15.5)\n    drafting.component(ctx, {\n      view: rtuDetail,\n      symbol: \"mechanical.roof_curb_rail\",\n      at: pt(-2, 1.5),\n      width: inch(8),\n      height: inch(14),\n    });\n    drafting.component(ctx, {\n      view: rtuDetail,\n      symbol: \"mechanical.roof_curb_rail\",\n      at: pt(58, 1.5),\n      width: inch(8),\n      height: inch(14),\n      mirror: true,\n    });\n\n    // Carrier 50FEQ RTU cabinet body + top condenser fan discharge shroud + right OA intake hood (resting at y = 15.5)\n    drafting.region(ctx, {\n      view: rtuDetail,\n      rect: { at: pt(0, 15.5), width: inch(64), height: inch(34) },\n      hatch: \"solid\",\n      tone: \"screened\",\n      boundary: false,\n    });\n    drafting.rect(ctx, { view: rtuDetail, at: pt(0, 15.5), width: inch(64), height: inch(34), lineStyle: \"wide\" });\n    // Internal equipment panel division lines\n    drafting.line(ctx, { view: rtuDetail, from: pt(24, 15.5), to: pt(24, 49.5), lineStyle: \"thin\" });\n    drafting.line(ctx, { view: rtuDetail, from: pt(48, 15.5), to: pt(48, 49.5), lineStyle: \"thin\" });\n    // Top condenser fan discharge collar\n    drafting.rect(ctx, { view: rtuDetail, at: pt(8, 49.5), width: inch(22), height: inch(4), lineStyle: \"medium\" });\n    // Right outdoor-air rain hood with bird screen\n    drafting.chain(ctx, {\n      view: rtuDetail,\n      points: [pt(64, 39.5), pt(74, 31.5), pt(74, 23.5), pt(64, 23.5)],\n      lineStyle: \"medium\",\n    });\n\n    // Equipment center label inside clean cabinet interior\n    drafting.note(ctx, {\n      view: rtuDetail,\n      at: pt(8, 37.5),\n      width: inch(2.9),\n      textHeight: inch(0.1),\n      align: \"center\",\n      bold: true,\n      text: \"CARRIER 50FEQ HEAT PUMP RTU\\nRTU-1 (3T) / RTU-2 (7.5T) / RTU-3 (4T)\",\n    });\n\n    // Supply & Return vertical drop ducts connecting RTU curb openings straight down into concentric transition box (y = -40)\n    // (Left: Supply duct x = 10..24; Right: Return duct x = 40..54 — lined internally with 1\" NFPA 90A acoustic liner)\n    drafting.line(ctx, { view: rtuDetail, from: pt(10, 15.5), to: pt(10, -40), lineStyle: \"wide\" });\n    drafting.line(ctx, { view: rtuDetail, from: pt(24, 15.5), to: pt(24, -40), lineStyle: \"wide\" });\n    // 1\" internal acoustic duct liner strips along supply duct interior walls\n    drafting.region(ctx, {\n      view: rtuDetail,\n      rect: { at: pt(10, -35), width: inch(1.5), height: inch(28) },\n      hatch: \"acoustic\",\n      tone: \"halftone\",\n      lineStyle: \"thin\",\n    });\n    drafting.region(ctx, {\n      view: rtuDetail,\n      rect: { at: pt(22.5, -35), width: inch(1.5), height: inch(28) },\n      hatch: \"acoustic\",\n      tone: \"halftone\",\n      lineStyle: \"thin\",\n    });\n    // Supply volume damper + airflow direction arrow (downward)\n    drafting.line(ctx, { view: rtuDetail, from: pt(11.5, -14), to: pt(22.5, -18), lineStyle: \"medium\" });\n    drafting.circle(ctx, { view: rtuDetail, center: pt(17, -16), radius: inch(0.75), lineStyle: \"thin\" });\n    drafting.component(ctx, { view: rtuDetail, symbol: \"flow_arrow\", at: pt(15.5, -24), width: inch(5), height: inch(3), rotationDeg: -90 });\n\n    // Right: Return vertical duct (x = 40..54) with 1\" internal acoustic liner & return airflow arrow (upward)\n    drafting.line(ctx, { view: rtuDetail, from: pt(40, 15.5), to: pt(40, -40), lineStyle: \"wide\" });\n    drafting.line(ctx, { view: rtuDetail, from: pt(54, 15.5), to: pt(54, -40), lineStyle: \"wide\" });\n    drafting.region(ctx, {\n      view: rtuDetail,\n      rect: { at: pt(40, -35), width: inch(1.5), height: inch(28) },\n      hatch: \"acoustic\",\n      tone: \"halftone\",\n      lineStyle: \"thin\",\n    });\n    drafting.region(ctx, {\n      view: rtuDetail,\n      rect: { at: pt(52.5, -35), width: inch(1.5), height: inch(28) },\n      hatch: \"acoustic\",\n      tone: \"halftone\",\n      lineStyle: \"thin\",\n    });\n    drafting.component(ctx, { view: rtuDetail, symbol: \"flow_arrow\", at: pt(48.5, -18), width: inch(5), height: inch(3), rotationDeg: 90 });\n\n    // Ceiling line & Ruskin 01-530 concentric diffuser transition plenum box\n    drafting.line(ctx, { view: rtuDetail, from: pt(-12, -52), to: pt(8, -52), lineStyle: \"medium\" });\n    drafting.line(ctx, { view: rtuDetail, from: pt(56, -52), to: pt(76, -52), lineStyle: \"medium\" });\n    drafting.component(ctx, {\n      view: rtuDetail,\n      symbol: \"mechanical.concentric_diffuser\",\n      at: pt(8, -53),\n      width: inch(48),\n      height: inch(13),\n    });\n\n    // Real CAD dimensions (service clearance, condenser clearance, curb height) — cleanly outside dashed clearance boxes\n    drafting.dimension(ctx, {\n      view: rtuDetail,\n      from: pt(-48, 49.5),\n      to: pt(0, 49.5),\n      offset: inch(-0.45),\n      suffix: \" SERVICE CLR.\",\n    });\n    drafting.dimension(ctx, {\n      view: rtuDetail,\n      from: pt(64, 49.5),\n      to: pt(100, 49.5),\n      offset: inch(-0.45),\n      suffix: \" COND. / OA CLR.\",\n    });\n    drafting.dimension(ctx, {\n      view: rtuDetail,\n      from: pt(0, 1.5),\n      to: pt(0, 15.5),\n      offset: inch(-0.55),\n      suffix: \" CURB\",\n    });\n\n    // Margin-aligned callout stacks (zero overlaps, opaque masks, horizontal-shoulder filled arrows, clean non-crossing routing)\n    drafting.calloutStack(ctx, {\n      view: rtuDetail,\n      side: \"left\",\n      x: inch(-54),\n      topY: inch(20),\n      width: inch(2.85),\n      notes: [\n        { text: \"14\\\" INSULATED ROOF CURB\\n(CRRFCURB) W/ CANT & FLASHING\", to: pt(0.5, 11.5) },\n      ],\n    });\n    drafting.calloutStack(ctx, {\n      view: rtuDetail,\n      side: \"left\",\n      x: inch(-54),\n      topY: inch(3.5),\n      width: inch(2.85),\n      notes: [\n        { text: \"SLOPED PEMB ROOF DECK\\nW/ RIGID INSULATION & MEMBRANE\", to: pt(-28, -0.5) },\n      ],\n    });\n    drafting.calloutStack(ctx, {\n      view: rtuDetail,\n      side: \"left\",\n      x: inch(-54),\n      topY: inch(-16),\n      width: inch(2.85),\n      notes: [\n        { text: \"SUPPLY DROP DUCT W/ BAL. DAMPER\\nSEAL ALL JOINTS (SMACNA CLASS A)\", to: pt(10, -20) },\n        { text: \"FINISHED CEILING PLANE\", to: pt(-6, -52) },\n      ],\n    });\n    drafting.calloutStack(ctx, {\n      view: rtuDetail,\n      side: \"right\",\n      x: inch(106),\n      topY: inch(35),\n      width: inch(2.95),\n      notes: [\n        { text: \"OUTDOOR AIR INTAKE HOOD\\nW/ BIRD SCREEN & MOTORIZED DAMPER\", to: pt(74, 29) },\n      ],\n    });\n    drafting.calloutStack(ctx, {\n      view: rtuDetail,\n      side: \"right\",\n      x: inch(106),\n      topY: inch(-16),\n      width: inch(2.95),\n      notes: [\n        { text: \"RETURN DROP DUCT W/ 1\\\" INTERNAL\\nACOUSTIC DUCT LINER (NFPA 90A)\", to: pt(54, -20) },\n        { text: \"RUSKIN 01-530 CONCENTRIC DIFFUSER\\n4-WAY SUPPLY + CENTER EGGCRATE RETURN\", to: pt(56, -46) },\n      ],\n    });\n\n    drafting.fitCrop(ctx, rtuDetail, { margin: inch(0.35) });\n    const rtuQa = drafting.check(ctx, rtuDetail);\n\n    // ── DETAIL 2: TOILET EXHAUST FAN (EF-1A/1B) & 6\" Ø EXTERIOR HOODED WALL CAP ──\n    const fanDetail = drafting.view(ctx, {\n      name: \"TOILET EXHAUST FAN & HOODED WALL CAP DETAIL\",\n      scale: 16, // 3/4\" = 1'-0\"\n      discipline: \"mechanical\",\n    });\n\n    // Exterior wall assembly (CMU/masonry backup + interior gypsum board + batt insulation)\n    drafting.region(ctx, {\n      view: fanDetail,\n      rect: { at: pt(42, -14), width: inch(8), height: inch(42) },\n      hatch: \"masonry\",\n      tone: \"halftone\",\n      lineStyle: \"wide\",\n    });\n    drafting.region(ctx, {\n      view: fanDetail,\n      rect: { at: pt(40, -14), width: inch(2), height: inch(42) },\n      hatch: \"gypsum\",\n      tone: \"screened\",\n      lineStyle: \"thin\",\n    });\n    // Top and bottom wall break lines set slightly inboard so the zig-zag cut mask cleanly slices off the wall edges & masonry hatch\n    drafting.breakLine(ctx, { view: fanDetail, from: pt(37.5, 25.5), to: pt(52.5, 25.5), maskSide: \"left\", maskDepth: inch(5) });\n    drafting.breakLine(ctx, { view: fanDetail, from: pt(52.5, -11.5), to: pt(37.5, -11.5), maskSide: \"left\", maskDepth: inch(5) });\n\n    // Restroom ceiling plane (gypsum board + cavity batt insulation)\n    drafting.region(ctx, {\n      view: fanDetail,\n      rect: { at: pt(-10, -2), width: inch(50), height: inch(2) },\n      hatch: \"gypsum\",\n      tone: \"screened\",\n      lineStyle: \"medium\",\n    });\n    drafting.line(ctx, { view: fanDetail, from: pt(-10, 0), to: pt(40, 0), lineStyle: \"wide\" });\n    drafting.breakLine(ctx, { view: fanDetail, from: pt(-8.5, -4), to: pt(-8.5, 4), maskSide: \"left\", maskDepth: inch(4) });\n\n    // Ceiling cabinet exhaust fan (EF-1A/1B)\n    drafting.component(ctx, {\n      view: fanDetail,\n      symbol: \"mechanical.exhaust_fan_ceiling\",\n      at: pt(2, -1),\n      width: inch(14),\n      height: inch(13),\n    });\n\n    // 6\" Ø rigid galvanized exhaust duct sloped slightly down toward exterior wall cap\n    // Opaque white mask fills the duct interior where it crosses the wall assembly so masonry hatch doesn't bleed through the duct.\n    drafting.region(ctx, {\n      view: fanDetail,\n      points: [pt(16, 9), pt(50, 7.5), pt(50, 1.5), pt(16, 3)],\n      masking: true,\n      boundary: false,\n    });\n    drafting.chain(ctx, {\n      view: fanDetail,\n      points: [pt(16, 9), pt(50, 7.5)],\n      lineStyle: \"wide\",\n    });\n    drafting.chain(ctx, {\n      view: fanDetail,\n      points: [pt(16, 3), pt(50, 1.5)],\n      lineStyle: \"wide\",\n    });\n    // Duct centerline + airflow arrow\n    drafting.line(ctx, { view: fanDetail, from: pt(16, 6), to: pt(50, 4.5), lineStyle: \"center\" });\n    drafting.component(ctx, { view: fanDetail, symbol: \"flow_arrow\", at: pt(26, 4), width: inch(8), height: inch(3.5), rotationDeg: -2.5 });\n\n    // 6\" Ø exterior hooded wall cap (LOUV-1A/1B) w/ integral BDD & 1/4\" bird screen\n    drafting.component(ctx, {\n      view: fanDetail,\n      symbol: \"mechanical.hooded_louver\",\n      at: pt(50, -0.5),\n      width: inch(10),\n      height: inch(10),\n    });\n\n    // Real CAD dimensions (placed cleanly in open margins outside wall & fan)\n    drafting.dimension(ctx, {\n      view: fanDetail,\n      from: pt(0, -4),\n      to: pt(16, -4),\n      offset: inch(0.45),\n      suffix: \" FAN HSG.\",\n    });\n    drafting.dimension(ctx, {\n      view: fanDetail,\n      from: pt(40, -14),\n      to: pt(50, -14),\n      offset: inch(0.45),\n    });\n\n    // Clean margin callouts on left & right (zero overlaps with geometry)\n    drafting.calloutStack(ctx, {\n      view: fanDetail,\n      side: \"left\",\n      x: inch(-16),\n      topY: inch(24),\n      width: inch(3.15),\n      notes: [\n        { text: \"CEILING EXHAUST FAN (EF-1A/1B)\\nGREENHECK SP-A50-QD (70 CFM)\\nINTEGRAL BACKDRAFT DAMPER\", to: pt(6, 11) },\n        { text: \"6\\\" Ø RIGID GALV. EXHAUST DUCT\\nSLOPE 1/4\\\" PER FT TO EXTERIOR\\nINSULATE W/ R-6 WRAP IN UNCOND. SPACE\", to: pt(20, 8.8) },\n        { text: \"RESTROOM CEILING (9'-0\\\" AFF)\", to: pt(-2, 0) },\n      ],\n    });\n    drafting.calloutStack(ctx, {\n      view: fanDetail,\n      side: \"right\",\n      x: inch(66),\n      topY: inch(24),\n      width: inch(2.85),\n      notes: [\n        { text: \"EXTERIOR WALL ASSEMBLY\\nSEAL DUCT PENETRATION WEATHERTIGHT\", to: pt(48, 18) },\n        { text: \"6\\\" Ø HOODED WALL CAP (LOUV-1A/1B)\\nW/ INTEGRAL BDD & 1/4\\\" BIRD SCREEN\\nCAULK FLANGE PERIMETER\", to: pt(57, 6) },\n      ],\n    });\n\n    drafting.fitCrop(ctx, fanDetail, { margin: inch(0.35) });\n    const fanQa = drafting.check(ctx, fanDetail);\n\n    // ── PLACE BOTH DETAILS ON SHEET M-501 ──\n    const sheet = documents.sheet(ctx, {\n      number: \"M-501\",\n      name: \"MECHANICAL DETAILS & SCHEMATICS\",\n      discipline: \"mechanical\",\n    });\n    documents.place(ctx, sheet, rtuDetail, { x: inch(14.5), y: inch(15.8) });\n    documents.place(ctx, sheet, fanDetail, { x: inch(14.5), y: inch(6.2) });\n\n    ctx.report(\"Detail QA\", {\n      rtuDetail: { ok: rtuQa.ok, items: rtuQa.itemCount, notes: rtuQa.noteCount, dims: rtuQa.dimCount, issues: rtuQa.issues },\n      fanDetail: { ok: fanQa.ok, items: fanQa.itemCount, notes: fanQa.noteCount, dims: fanQa.dimCount, issues: fanQa.issues },\n    });\n    ctx.label(\"Mechanical Details sheet M-501 (RTU curb & toilet exhaust fan)\");\n  },\n});\n",
  "plumbing-riser": "/**\n * Plumbing riser: toilet rooms on two floors, drained by a stack into a\n * sloped building drain, every pipe sized by the plumbing code.\n *\n * The script counts drainage fixture units (DFU) and water supply fixture\n * units (WSFU) for the fixtures it places, sizes the floor branches, the\n * stack and the building drain with the code's drain sizing calc (2021\n * plumbing code tables), and the water demand with the Hunter curve. Then it\n * routes the piping with its fall, connects the fixtures, and tags the drain\n * and branches with their size and slope.\n *\n * Run it: paste it to an assistant connected to the MutinyBIM tool server\n * (\"run this script\"), or `npm run example -- plumbing-riser`.\n */\nimport { defineScript, units, routes, building, equipment, documents } from \"@permitzip/bim-script\";\n\nconst ft = units.ft;\nconst at = (x: number, y: number) => ({ x: ft(x), y: ft(y) });\n\n/** Fixture units per fixture, public use (plumbing code drainage and supply fixture unit tables). */\nconst FIXTURES = [\n  { type: \"builtin:plumbing-wc-flush-tank@1\", mark: \"WC\", x: 4, dfu: 4, wsfu: 5 },\n  { type: \"builtin:plumbing-wc-flush-tank@1\", mark: \"WC\", x: 8, dfu: 4, wsfu: 5 },\n  { type: \"builtin:plumbing-lavatory@1\", mark: \"L\", x: 12, dfu: 1, wsfu: 2 },\n  { type: \"builtin:plumbing-lavatory@1\", mark: \"L\", x: 15, dfu: 1, wsfu: 2 },\n];\n/** 1/4 in per ft: the code minimum for drains 3 in and smaller, and the slope the sizing table is read at. */\nconst SLOPE = { rise: units.in(0.25), per: ft(1) };\n\nexport default defineScript({\n  kind: \"route\",\n  reads: { levels: true },\n  parameters: {},\n  run(ctx) {\n    /** Size one drain by the code (3 in. at least where a water closet drains to it); the answer is nominal inches. */\n    const drainSize = (role: \"building_drain\" | \"horizontal_branch\" | \"stack\", dfu: number): number => {\n      const result = ctx.calc({ calc: \"plumbing.size_drain\", inputs: { role, dfu, slope_in_per_ft: 0.25, serves_water_closet: true }, plumbingEdition: \"2021\" });\n      if (!result.ok) throw new Error(result.reason);\n      return Number(result.run.values.find((v) => v.key === \"size_nominal_in\")?.value);\n    };\n\n    const floorDfu = FIXTURES.reduce((sum, f) => sum + f.dfu, 0);\n    const floorWsfu = FIXTURES.reduce((sum, f) => sum + f.wsfu, 0);\n    const floors = [building.level(ctx, { name: \"Level 1\", elevation: ft(0) }), building.level(ctx, { name: \"Level 2\", elevation: ft(12) })];\n    const sanitary = { id: \"san-1\", kind: \"sanitary\", name: \"Sanitary\" } as const;\n    const branchIn = drainSize(\"horizontal_branch\", floorDfu);\n    const stackIn = drainSize(\"stack\", floorDfu);\n    const drainIn = drainSize(\"building_drain\", floorDfu * floors.length);\n\n    const [ground, upper] = floors;\n    if (!ground || !upper) throw new Error(\"Two floors expected.\");\n    const pipe = (inches: number) => routes.pipe(units.in(inches), \"pvc\");\n    const lastPiece = (route: { segment(n: number): string }) => {\n      // The kernel numbers a route's pieces s1, s2, … from its start.\n      let n = 1;\n      while (ctx.model.find(route.segment(n + 1))) n += 1;\n      return route.segment(n);\n    };\n\n    // Fixtures in the same spot on each floor: two water closets and two lavatories along one wall.\n    const fixturesOn = (level: string, floor: number) => FIXTURES.map((f) => equipment.place(ctx, { level, type: f.type, at: at(f.x, 4), mark: `${f.mark}-${floor}` }));\n\n    // Level 2: a branch under the floor, falling west to the stack at x = 1 ft.\n    const branch = routes.along(ctx, { level: upper, domain: \"pipe\", size: pipe(branchIn), system: sanitary, height: ft(-1), slope: SLOPE, flow: \"with_points\", points: [at(17, 2), at(2, 2)] });\n    routes.connectInto(ctx, { from: fixturesOn(upper, 2).map((p) => ({ elementId: p.id, port: \"w\" })), into: branch.segment(1) });\n\n    // The stack: drawn on Level 1, where it ends. It leaves the branch end straight (1 ft on), then drops\n    // to 18 in under the Level 1 floor. The first point takes the branch end's height, after its fall.\n    const stack = routes.along(ctx, { level: ground, domain: \"pipe\", size: pipe(stackIn), system: sanitary, from: routes.atRunEnd(branch.segment(1), \"end\"), points: [at(1, 2), { ...at(1, 2), height: ft(-1.5) }] });\n\n    // The building drain: from the stack's foot (an elbow turns it), east 2.5 ft under the Level 1 floor to the street, falling 1/4 in per foot.\n    const drain = routes.along(ctx, { level: ground, domain: \"pipe\", size: pipe(drainIn), system: sanitary, from: routes.atRunEnd(lastPiece(stack), \"end\"), height: ft(-2.5), slope: SLOPE, flow: \"with_points\", points: [at(2, 2), at(60, 2)] });\n\n    // Level 1's fixtures drain straight into the building drain under them.\n    routes.connectInto(ctx, { from: fixturesOn(ground, 1).map((p) => ({ elementId: p.id, port: \"w\" })), into: lastPiece(drain) });\n\n    // Water demand for every fixture, from the Hunter curve.\n    const demand = ctx.calc({ calc: \"plumbing.hunter_demand\", inputs: { wsfu: floorWsfu * floors.length, building_type: \"office\" } });\n    const gpm = demand.ok ? Number(demand.run.values.find((v) => v.key === \"design_gpm\")?.value) : null;\n\n    // A plumbing plan of Level 1, the building drain tagged with its size, slope and fixture units.\n    const plan = documents.planView(ctx, { level: ground, name: \"Level 1 - Plumbing\", scale: 48, discipline: \"plumbing\" });\n    documents.tag(ctx, { view: plan, element: lastPiece(drain), at: at(40, -3), fields: [\"pipe.size\", \"pipe.slope\", \"pipe.carries.dfu\"] });\n    const sheet = documents.sheet(ctx, { number: \"P-101\", name: \"Level 1 plumbing plan\" });\n    documents.place(ctx, sheet, plan, { x: units.mm(300), y: units.mm(280) });\n\n    ctx.label(`Riser: ${floorDfu * floors.length} DFU, ${branchIn} in branches, ${stackIn} in stack, ${drainIn} in building drain at 1/4 in per ft${gpm ? `, ${Math.round(gpm)} gpm water demand` : \"\"}`);\n  },\n});\n",
  "rooftop-unit": "/**\n * Rooftop unit: a 10 ton unit on the roof, ducted down into two rooms.\n *\n * The script sizes the supply and return ducts with the duct sizing read\n * (the system's friction and velocity limits), builds the unit's part type\n * with connectors of that size, places it on the roof, and routes its\n * supply and return down into the rooms. Then it tags the ducts on a plan\n * and puts an equipment schedule on a sheet.\n *\n * Run it: paste it to an assistant connected to the MutinyBIM tool server\n * (\"run this script\"), or `npm run example -- rooftop-unit`.\n */\nimport { defineScript, units, routes, parts, building, equipment, documents } from \"@permitzip/bim-script\";\n\nconst ft = units.ft;\nconst at = (x: number, y: number) => ({ x: ft(x), y: ft(y) });\n\n/** 10 tons at 400 CFM per ton. */\nconst SUPPLY_CFM = 4000;\n\nexport default defineScript({\n  kind: \"route\",\n  reads: { levels: true },\n  parameters: {},\n  run(ctx) {\n    // The building: one floor, 60 ft x 30 ft, two rooms side by side, a 10 ft ceiling.\n    const level = building.level(ctx, { name: \"Level 1\", elevation: ft(0) });\n    building.walls(ctx, { level, points: [at(0, 0), at(60, 0), at(60, 30), at(0, 30)], closed: true, thickness: units.in(8), height: ft(14) });\n    building.walls(ctx, { level, points: [at(30, 0), at(30, 30)], thickness: units.in(5), height: ft(14) });\n    building.spaceInWalls(ctx, { level, inside: at(15, 15), number: \"101\", name: \"Classroom\" });\n    building.spaceInWalls(ctx, { level, inside: at(45, 15), number: \"102\", name: \"Classroom\" });\n\n    // Size the main ducts first: 12 in deep to fit above the ceiling. Sizes come back in mm.\n    const advice = ctx.read<{ suggested: { size: { width: number; height: number }; velocityFpm: number } }>(\"mechanical.duct_size\", { cfm: SUPPLY_CFM, shape: \"rect\", height_mm: 305, system_kind: \"supply_air\" });\n    const { width, height } = advice.suggested.size;\n    const duct = routes.rect(units.mm(width), units.mm(height));\n\n    // The unit's part type: a box with supply and return openings on its underside, sized like the ducts.\n    // A route or layout script saves a new type as an edit (save_part_types). It never calls\n    // ctx.parts.define (only a part script does); to use a type the model or library already has,\n    // list its id in reads.partTypes and place it with equipment.place.\n    const rtu = parts.part(\"Rooftop unit\", { type: \"10 ton\", category: \"mechanical_equipment\" });\n    rtu.box({ length: units.in(120), width: units.in(60), height: units.in(48) });\n    for (const [id, label, systemKind, x] of [[\"supply\", \"Supply\", \"supply_air\", -30], [\"return\", \"Return\", \"return_air\", 30]] as const) {\n      rtu.connector(\"bottom\", { id, label, domain: \"duct\", systemKind, shape: \"rect\", width: units.mm(width), height: units.mm(height), offset: [units.in(x), units.in(0)] });\n    }\n    ctx.edit({ type: \"save_part_types\", label: \"Rooftop unit, 10 ton\", types: [{ typeId: \"example.rtu.10t\", definition: rtu.build() }] });\n\n    // On the roof: its base 14 ft above the floor, over the middle wall.\n    const unit = equipment.place(ctx, { level, type: \"example.rtu.10t\", at: at(30, 15), height: ft(14), mark: \"RTU-1\" });\n\n    // Supply down into room 101, return down into room 102, both at 11 ft (above the 10 ft ceiling).\n    routes.along(ctx, { level, domain: \"duct\", size: duct, system: { id: \"sa-1\", kind: \"supply_air\", name: \"Supply air\" }, height: ft(11), from: unit.connector(\"supply\"), points: [at(15, 15), at(8, 15)] });\n    routes.along(ctx, { level, domain: \"duct\", size: duct, system: { id: \"ra-1\", kind: \"return_air\", name: \"Return air\" }, height: ft(11), from: unit.connector(\"return\"), points: [at(45, 15), at(52, 15)] });\n\n    // A mechanical plan cut above the ducts, every duct tagged with its size.\n    const plan = documents.planView(ctx, { level, name: \"Level 1 - Mechanical\", scale: 48, cutHeight: ft(12), discipline: \"mechanical\" });\n    documents.autoTag(ctx, { view: plan, categories: [\"duct\", \"equipment\"] });\n\n    // The plan and an equipment schedule on sheets.\n    const planSheet = documents.sheet(ctx, { number: \"M-101\", name: \"Level 1 mechanical plan\" });\n    documents.place(ctx, planSheet, plan, { x: units.mm(300), y: units.mm(280) });\n    const schedule = documents.schedule(ctx, { name: \"Mechanical equipment schedule\", category: \"mechanical_equipment\", columns: [\"mark\", \"type_name\", \"level\"] });\n    const scheduleSheet = documents.sheet(ctx, { number: \"M-601\", name: \"Mechanical schedules\" });\n    documents.place(ctx, scheduleSheet, schedule, { x: units.mm(200), y: units.mm(400) });\n\n    ctx.label(`RTU-1 (${SUPPLY_CFM} CFM) with ${Math.round(width / 25.4)}x${Math.round(height / 25.4)} supply and return ducts at ${Math.round(advice.suggested.velocityFpm)} fpm`);\n  },\n});\n",
  "small-office": "/**\n * Small office: two floors of a 40 ft x 30 ft office.\n *\n * Each floor gets exterior walls, interior walls that split it into an open\n * office, a conference room and a private office, doors and windows, and\n * rooms found from the walls around them (nobody draws a room outline), and\n * a ceiling in each room. Then each floor gets a plan on its own sheet.\n *\n * Level arguments are level ids: building.level returns the id every call\n * below passes as `level`. On a model that already has levels, read them\n * (reads.levels: true) and pass an id from ctx.model.levels(); the kit's\n * helpers also take the name of exactly one level (\"Level 2\").\n *\n * Run it: paste it to an assistant connected to the MutinyBIM tool server\n * (\"run this script\"), or `npm run example -- small-office`.\n */\nimport { defineScript, units, building, documents } from \"@permitzip/bim-script\";\n\nconst ft = units.ft;\nconst at = (x: number, y: number) => ({ x: ft(x), y: ft(y) });\n\nexport default defineScript({\n  kind: \"layout\",\n  reads: { levels: true },\n  parameters: {},\n  run(ctx) {\n    ctx.label(\"Small office: two floors with walls, rooms, ceilings, doors and windows, and a plan sheet per floor\");\n    const made: { level: string; id: string; rooms: string[] }[] = [];\n\n    const floors = [\n      { name: \"Level 1\", elevation: ft(0), sheet: \"A-101\" },\n      { name: \"Level 2\", elevation: ft(12), sheet: \"A-102\" },\n    ];\n\n    for (const floor of floors) {\n      const level = building.level(ctx, { name: floor.name, elevation: floor.elevation });\n\n      // The outside: four walls, 8 in thick, closed back to the first corner.\n      // Wall 1 runs along the south side, wall 3 along the north.\n      const outside = building.walls(ctx, { level, points: [at(0, 0), at(40, 0), at(40, 30), at(0, 30)], closed: true, thickness: units.in(8), height: ft(11) });\n\n      // Inside: one wall north to south at 24 ft, and one east of it at 15 ft.\n      const split = building.walls(ctx, { level, points: [at(24, 0), at(24, 30)], thickness: units.in(5), height: ft(11) });\n      const office = building.walls(ctx, { level, points: [at(24, 15), at(40, 15)], thickness: units.in(5), height: ft(11) });\n\n      // Doors are placed along a wall, from its start. The entry is on the ground floor only.\n      if (floor.name === \"Level 1\") building.door(ctx, { wall: outside.element(1), along: ft(10), width: units.in(36), mark: \"101A\" });\n      building.door(ctx, { wall: split.element(1), along: ft(22), width: units.in(36) });\n      building.door(ctx, { wall: office.element(1), along: ft(4), width: units.in(36) });\n\n      // Windows on the north wall (it runs east to west, so 6 ft along it is near the east end).\n      for (const along of [6, 18, 30]) building.window(ctx, { wall: outside.element(3), along: ft(along), width: ft(4), height: ft(5) });\n\n      // Rooms from the walls: one point inside each, the kernel traces the enclosure.\n      const n = floor.name === \"Level 1\" ? 100 : 200;\n      const open = building.spaceInWalls(ctx, { level, inside: at(10, 15), number: `${n + 1}`, name: \"Open office\" });\n      const conference = building.spaceInWalls(ctx, { level, inside: at(32, 7), number: `${n + 2}`, name: \"Conference\" });\n      const privateOffice = building.spaceInWalls(ctx, { level, inside: at(32, 22), number: `${n + 3}`, name: \"Office\" });\n\n      // A 9 ft ceiling in each room, its outline 1 ft inside the walls (units.* values, no millimetres by hand).\n      const inset = (x0: number, y0: number, x1: number, y1: number) => [at(x0 + 1, y0 + 1), at(x1 - 1, y0 + 1), at(x1 - 1, y1 - 1), at(x0 + 1, y1 - 1)];\n      building.ceiling(ctx, { level, space: open, outline: inset(0, 0, 24, 30), height: ft(9) });\n      building.ceiling(ctx, { level, space: conference, outline: inset(24, 0, 40, 15), height: ft(9) });\n      building.ceiling(ctx, { level, space: privateOffice, outline: inset(24, 15, 40, 30), height: ft(9) });\n      made.push({ level: floor.name, id: level, rooms: [open, conference, privateOffice] });\n\n      // A plan of this floor on its own sheet, 1/4\" = 1'-0\".\n      const sheet = documents.sheet(ctx, { number: floor.sheet, name: `${floor.name} floor plan` });\n      const plan = documents.planView(ctx, { level, name: `${floor.name} - Plan`, scale: 48 });\n      documents.place(ctx, sheet, plan, { x: units.mm(300), y: units.mm(280) });\n    }\n\n    // What the script made, for the agent: it comes back as `report` beside the preview.\n    ctx.report(\"Levels and rooms\", made);\n  },\n});\n",
};
